/**
 * Looks up Linguist languages for the `language:` qualifier.
 *
 * The data is generated by `scripts/generate-languages.ts`.
 *
 * @module
 */

import data from './languages.generated.json'
import type { Language } from './plan.types'

function normalize(name: string): string {
  return name.toLowerCase().replace(/\s+/g, '-')
}

const byName = new Map<string, Language>()
for (const [name, language] of Object.entries(data.languages)) {
  const entry = { name, extensions: language.extensions, filenames: language.filenames }
  for (const key of [name, ...language.aliases]) {
    if (!byName.has(normalize(key))) byName.set(normalize(key), entry)
  }
}

const popular = new Set<string>(data.popular)

/** Shared extensions the ranking below gets wrong, pinned to the language most files with them are written in. */
const PREFERRED: Readonly<Record<string, string>> = {
  '.cfg': 'INI',
  '.cls': 'TeX',
  '.d': 'D',
  '.f': 'Fortran',
  '.for': 'Fortran',
  '.fs': 'F#',
  '.h': 'C',
  '.ms': 'Roff',
  '.sql': 'SQL',
  '.v': 'Verilog',
  '.yaml': 'YAML',
}

type Entry = (typeof data.languages)[keyof typeof data.languages]

/**
 * Orders languages competing for one extension: popular ones first, then one
 * whose primary (first) extension it is, then the one with more extensions
 * and filenames — a rough stand-in for how common it is.
 *
 * Breadth must come last: XML alone claims over a hundred extensions and
 * would otherwise take `.tsx` and many more.
 */
function rank(extension: string, [name, language]: [string, Entry]): number[] {
  return [
    popular.has(name) ? 0 : 1,
    language.extensions[0]?.toLowerCase() === extension ? 0 : 1,
    -(language.extensions.length + language.filenames.length),
  ]
}

function compareRanks(a: number[], b: number[]): number {
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return a[i]! - b[i]!
  return 0
}

const candidates = new Map<string, [string, Entry][]>()
const byFilename = new Map<string, string>()
for (const entry of Object.entries(data.languages)) {
  for (const extension of entry[1].extensions) {
    const key = extension.toLowerCase()
    candidates.set(key, [...(candidates.get(key) ?? []), entry])
  }
  for (const filename of entry[1].filenames) {
    if (!byFilename.has(filename.toLowerCase())) byFilename.set(filename.toLowerCase(), entry[0])
  }
}

const byExtension = new Map<string, string>(
  [...candidates].map(([extension, entries]) => [
    extension,
    PREFERRED[extension] ?? entries.toSorted((a, b) => compareRanks(rank(extension, a), rank(extension, b)))[0]![0],
  ]),
)

/**
 * Names the language a path most likely belongs to, for grouping results.
 *
 * An exact filename wins over an extension, and the longest matching extension
 * wins. An extension several languages share goes to a popular language first,
 * then to one whose primary extension it is, then to the broader language — so
 * `.md` is Markdown, `.ts` TypeScript, and `.tsx` TSX — with common misses such
 * as `.h` (C), `.yaml` (YAML), and `.sql` (SQL) pinned. Linguist's content
 * heuristics are not applied.
 *
 * @returns The canonical language name, or `undefined` for an unknown file type.
 */
export function languageOf(path: string): string | undefined {
  const name = path.slice(path.lastIndexOf('/') + 1).toLowerCase()
  const exact = byFilename.get(name)
  if (exact) return exact
  for (let dot = name.indexOf('.'); dot !== -1; dot = name.indexOf('.', dot + 1)) {
    const language = byExtension.get(name.slice(dot))
    if (language) return language
  }
  return undefined
}

/**
 * Finds a language by its name or one of its aliases.
 *
 * Membership is by extension and filename only, without Linguist's content
 * heuristics, so a `.h` file counts as C, C++, and Objective-C alike.
 *
 * Matching ignores case and treats whitespace as `-`, so `Common Lisp`,
 * `common lisp`, and `common-lisp` are the same language.
 *
 * @returns The language, or `undefined` when Linguist does not know it.
 */
export function findLanguage(name: string): Language | undefined {
  return byName.get(normalize(name))
}
